  1	import { EventEmitter } from 'node:events'
  2	
  3	const TERMINAL = new Set(['completed', 'failed', 'stopped', 'interrupted'])
  4	
  5	function createSseParser(onEvent) {
  6	  let buffer = ''
  7	  const consume = block => {
  8	    if (!block || block.startsWith(':')) return
  9	    let type = 'message'
 10	    const dataLines = []
 11	    for (const line of block.split(/\r?\n/)) {
 12	      if (line.startsWith('event:')) type = line.slice(6).trim()
 13	      else if (line.startsWith('data:')) dataLines.push(line.slice(5).trimStart())
 14	    }
 15	    if (!dataLines.length) return
 16	    const raw = dataLines.join('\n')
 17	    let data = raw
 18	    try { data = JSON.parse(raw) } catch {}
 19	    onEvent(type, data)
 20	  }
 21	  return {
 22	    push(chunk) {
 23	      buffer += String(chunk)
 24	      let boundary
 25	      while ((boundary = buffer.search(/\r?\n\r?\n/)) >= 0) {
 26	        const match = buffer.slice(boundary).match(/^(?:\r?\n){2}/)?.[0] || '\n\n'
 27	        consume(buffer.slice(0, boundary))
 28	        buffer = buffer.slice(boundary + match.length)
 29	      }
 30	    },
 31	    flush() {
 32	      consume(buffer.trim())
 33	      buffer = ''
 34	    },
 35	  }
 36	}
 37	
 38	function createExecutionIo({ headers = {}, socket = {}, onEvent }) {
 39	  const req = new EventEmitter()
 40	  req.headers = { ...headers }
 41	  req.socket = { remoteAddress: '127.0.0.1', ...socket }
 42	  req.destroyed = false
 43	
 44	  const res = new EventEmitter()
 45	  const parser = createSseParser(onEvent)
 46	  res.statusCode = 200
 47	  res.headers = {}
 48	  res.writableEnded = false
 49	  res.setHeader = (name, value) => { res.headers[String(name).toLowerCase()] = value }
 50	  res.writeHead = (code, responseHeaders = {}) => {
 51	    res.statusCode = code
 52	    for (const [name, value] of Object.entries(responseHeaders)) res.setHeader(name, value)
 53	    return res
 54	  }
 55	  res.write = chunk => {
 56	    if (res.writableEnded) return false
 57	    parser.push(chunk)
 58	    return true
 59	  }
 60	  res.end = chunk => {
 61	    if (res.writableEnded) return res
 62	    if (chunk != null) parser.push(chunk)
 63	    parser.flush()
 64	    res.writableEnded = true
 65	    res.emit('finish')
 66	    return res
 67	  }
 68	
 69	  let closed = false
 70	  const close = () => {
 71	    if (closed) return
 72	    closed = true
 73	    req.destroyed = true
 74	    req.emit('close')
 75	  }
 76	  return { req, res, close }
 77	}
