 79	export function createRunManager({ store, eventLog, executeChat, instanceId, onSessionUpdated = null }) {
 80	  const executions = new Map()
 81	
 82	  const append = (run, type, data = {}) => eventLog.append({
 83	    runId: run.id,
 84	    sessionId: run.sessionId,
 85	    type,
 86	    data,
 87	  })
 88	
 89	  const finish = (runId, status, data = {}) => {
 90	    const current = store.get(runId)
 91	    if (!current || TERMINAL.has(current.status)) return current
 92	    const updated = store.update(runId, {
 93	      status,
 94	      ...(status === 'completed' ? { completedAt: new Date().toISOString() } : {}),
 95	      ...(status === 'failed' ? { failedAt: new Date().toISOString(), error: data.message || 'run_failed' } : {}),
 96	      ...(status === 'stopped' ? { stoppedAt: new Date().toISOString() } : {}),
 97	    })
 98	    append(updated, status, data)
 99	    return updated
100	  }
101	
102	  const start = async control => {
103	    const initial = store.get(control.runId)
104	    if (!initial || TERMINAL.has(initial.status)) return
105	    if (control.stopRequested) {
106	      finish(initial.id, 'stopped', { reason: 'stopped_before_start' })
107	      executions.delete(initial.id)
108	      return
109	    }
110	
111	    const running = store.update(initial.id, { status: 'running', startedAt: new Date().toISOString() })
112	    append(running, 'run_started', { status: 'running' })
113	    let sawError = null
114	    const io = createExecutionIo({
115	      headers: control.context.headers,
116	      socket: control.context.socket,
117	      onEvent(type, data) {
118	        const current = store.get(running.id)
119	        append(current || running, type, data)
120	        if (type === 'error') sawError = data
121	      },
122	    })
123	    control.close = io.close
124	
125	    if (control.stopRequested) io.close()
126	    try {
127	      await executeChat(io.req, io.res, control.body)
128	      if (!io.res.writableEnded) io.res.end()
129	      const current = store.get(running.id)
130	      if (control.stopRequested || current?.status === 'stopping') {
131	        finish(running.id, 'stopped', { reason: 'user_stop' })
132	      } else if (sawError || io.res.statusCode >= 400) {
133	        const message = sawError?.message || sawError?.error || `HTTP ${io.res.statusCode}`
134	        finish(running.id, 'failed', { message })
135	      } else {
136	        // executeChat 返回时，聊天 JSONL 已经完成本轮写入；先通知前端刷新历史，再发布 Run 终态。
137	        // 这样会话记录不会等到下一次手动刷新或列表缓存自然过期才出现。
138	        const committed = store.get(running.id)
139	        try { onSessionUpdated?.({ run: committed || running }) } catch {}
140	        append(committed || running, 'session_updated', { sessionId: running.sessionId })
141	        finish(running.id, 'completed', {})
142	      }
143	    } catch (error) {
144	      const current = store.get(running.id)
145	      if (control.stopRequested || current?.status === 'stopping') {
146	        finish(running.id, 'stopped', { reason: 'user_stop' })
147	      } else {
148	        finish(running.id, 'failed', { message: String(error?.message || error) })
149	      }
150	    } finally {
151	      executions.delete(running.id)
152	    }
153	  }
154	
155	  return {
156	    create(body, context = {}) {
157	      if (!body?.sessionId) throw Object.assign(new Error('sessionId_required'), { code: 'invalid_request' })
158	      if (!body?.clientRequestId) throw Object.assign(new Error('clientRequestId_required'), { code: 'invalid_request' })
159	      const active = store.findActiveBySession(body.sessionId)
160	      if (active) {
161	        if (active.clientRequestId === body.clientRequestId) return active
162	        throw Object.assign(new Error('session_busy'), { code: 'session_busy', activeRunId: active.id })
163	      }
164	
165	      const run = store.create({ ...body, ownerId: instanceId })
166	      if (TERMINAL.has(run.status) || executions.has(run.id)) return run
167	      const control = {
168	        runId: run.id,
169	        body: { ...body },
170	        context: { headers: context.headers || {}, socket: context.socket || {} },
171	        close: null,
172	        stopRequested: false,
173	      }
174	      executions.set(run.id, control)
175	      queueMicrotask(() => start(control))
176	      return run
177	    },
178	    get(runId) { return store.get(runId) },
179	    readAfter(runId, after) { return eventLog.readAfter(runId, after) },
180	    subscribe(runId, listener) { return eventLog.subscribe(runId, listener) },
181	    stop(runId) {
182	      const run = store.get(runId)
183	      if (!run) throw Object.assign(new Error('run_not_found'), { code: 'run_not_found' })
184	      if (TERMINAL.has(run.status)) return run
185	      const control = executions.get(runId)
186	      if (control?.stopRequested) return store.get(runId)
187	      if (control) control.stopRequested = true
188	      const stopping = store.update(runId, { status: 'stopping', stopRequestedAt: new Date().toISOString() })
189	      if (control?.close) control.close()
190	      else if (!control) finish(runId, 'stopped', { reason: 'execution_missing' })
191	      return stopping
192	    },
193	    recover() {
194	      const orphaned = store.markOrphanedInterrupted(instanceId)
195	      for (const run of orphaned) append(run, 'interrupted', { reason: 'server_restarted' })
196	      return orphaned
197	    },
198	  }
199	}

