498	// 统一对话循环：openai 兼容 API → tool_calls 循环 → 思考提取
499	async function handleChat(req, res, body) {
500	  let message = typeof body.message === "string" ? body.message.trim() : "";
501	  const sessionId = typeof body.sessionId === "string" ? body.sessionId : null;
502	  // 限速（2026-08-29）：公网暴露下防脚本刷模型接口烧钱，30 次/分钟 per token+IP
503	  if (!rateLimit(rateLimitKey(req, "chat"), 30, 60000)) {
504	    return json(res, 429, { error: "请求过于频繁（30次/分钟），请稍后再试" });
505	  }
506	  // 外部思考调试开关：请求级 body.think=true 或全局 CONFIG.externalThinking
507	  const thinkOn = body.think === true || isExternalThinking();
508	  // 记录对话开始时会话行数（基线）：交付时只提取本轮新增的文件，避免历史文件重复推
509	  let chatBaseline = 0;
510	  console.log(`[chat] msg="${message.slice(0, 20)}" sid=${sessionId} model=${defaultModel?.provider}/${defaultModel?.id} agent=${body.model || ""}`);
511	  if (!message) return json(res, 400, { error: "消息不能为空" });
512	
513	  // @ 文件引用：把文件内容拼入消息上下文
514	  if (Array.isArray(body.files) && body.files.length) {
515	    const parts = [];
516	    for (const f of body.files.slice(0, 20)) {
517	      if (!f?.path || typeof f.content !== "string") continue;
518	      if (f.content.length > 150000) f.content = f.content.slice(0, 150000) + "\n…[已截断]";
519	      parts.push(`参考文件 ${f.path}：\n\`\`\`\n${f.content}\n\`\`\``);
520	    }
521	    if (parts.length) message = message + "\n\n" + parts.join("\n\n");
522	  }
523	
524	  // 图片附件：转给模型的 images 参数
525	  let images = [];
526	  if (Array.isArray(body.images) && body.images.length) {
527	    images = body.images
528	      .slice(0, 3)
529	      .filter(i => i?.data && i?.mimeType && i.data.length < 3 * 1024 * 1024)
530	      .map(i => ({ type: "image", data: i.data, mimeType: i.mimeType }));
531	  }
532	
533	  let entry;
534	  if (sessionId) {
535	    entry = await openSession(sessionId);
536	    if (!entry) return json(res, 404, { error: "会话不存在" });
537	  } else {
538	    // 未命名会话：body.fresh=true 表示用户点了「新建会话」→ 新建；否则复用上一个（打断续发同一会话）
539	    // 测试标记（2026-08-29）：x-pi-test 头 → 总是新建独立会话（不复用 lastUnnamed，防污染用户对话流），名字加 [真测] 前缀归入真测分组
540	    const isTest = String(req.headers?.["x-pi-test"] || "") === "1";
541	    if (isTest || body.fresh || !lastUnnamedEntry || activeSessions.get(lastUnnamedId) !== lastUnnamedEntry) {
542	      const id = await createSession(isTest ? `[真测] ${message.slice(0, 30) || "API测试"}` : undefined);
543	      lastUnnamedId = id;
544	      lastUnnamedEntry = activeSessions.get(id);
545	      entry = lastUnnamedEntry;
546	    } else {
547	      entry = lastUnnamedEntry;
548	      // 用户可能切换过模型：同步最新默认模型（用完整 runtime 模型，保证 compat 生效）
549	      try {
550	        if (defaultModel) {
551	          let fm = defaultModel;
552	          try { fm = modelRuntime.getModels().find(x => x.provider === defaultModel.provider && x.id === defaultModel.id) || defaultModel; } catch {}
553	          const ag = await ensureAgent(entry, fm);
554	          await ag.setModel(fm);
555	        }
556	      } catch {}
557	    }
558	  }
559	  // 记录对话开始时会话行数（交付去重基线：只推本轮新增文件）
560	  try {
561	    const sf = entry.sm.sessionFile;
562	    if (sf && fs.existsSync(sf)) chatBaseline = fs.readFileSync(sf, "utf8").split("\n").filter(Boolean).length;
563	  } catch {}
564	  // busy → 打断当前任务（对标 TUI interrupt：同一会话上处理新消息）
565	  if (entry.busy) {
566	    const curAgent = entry.agent;
567	    try { await curAgent.abort(); } catch {}
568	    // 等待当前任务释放 busy（abort 生效通常 2-3s）
569	    let waited = 0;
570	    while (entry.busy && waited < 8000) {
571	      await new Promise(r => setTimeout(r, 200));
572	      waited += 200;
573	    }
574	    if (entry.busy) {
575	      // abort 未生效（LLM 流卡死）→ 销毁旧 agent 重建，彻底释放
576	      try { curAgent.dispose(); } catch {}
577	      entry.busy = false;
578	      for (const [id, e] of activeSessions) if (e === entry) activeSessions.delete(id);
579	      console.log(`[pi-web] 会话 ${sessionId || "new"} 打断失败，已销毁卡住 agent 并重建`);
580	      if (sessionId) {
581	        entry = await openSession(sessionId);
582	        if (!entry) return json(res, 404, { error: "会话不存在" });
583	      } else {
584	        const id = await createSession();
585	        lastUnnamedId = id;
586	        lastUnnamedEntry = activeSessions.get(id);
587	        entry = lastUnnamedEntry;
588	      }
589	    }
590	  }
591	  // 代次机制：每次请求递增，旧请求 finally 只在代次未变时释放 busy（防快速重发竞态）
592	  entry.gen = (entry.gen || 0) + 1;
593	  const thisGen = entry.gen;
594	  entry.busy = true;
595	  entry.busySince = Date.now();
596	
597	  // /compact 手动压缩命令（Claude Code /compact 借鉴）：强制对早前历史生成结构化摘要，不消耗模型回合
598	  // 用法：/compact 或 /compact focus on <主题>；压缩结果写入会话（compaction 条目），返回摘要供前端展示
599	  const compactCmd = typeof message === "string" && message.trim().match(/^\/compact(?:\s+(?:focus\s+on\s+)?(.+))?$/i);
600	  if (compactCmd) {
601	    const compactFocus = (compactCmd[1] || "").trim();
602	    const sf = entry.sm.sessionFile;
603	    try {
604	      if (!sf || !fs.existsSync(sf)) return json(res, 400, { error: "会话文件不存在，无法压缩" });
605	      entry.busy = false;
606	      const r = await compactSession(sf, defaultModel, true, compactFocus);
607	      if (!r || r.skip) return json(res, 200, { compact: "skip", reason: r?.reason || "没有可压缩的内容（消息过少或摘要生成失败）" });
608	      console.log(`[pi-web] 手动 /compact 完成: focus=${compactFocus || "-"} retained=${r.retained}`);
609	      return json(res, 200, { compact: "done", focus: compactFocus, retained: r.retained, summary: String(r.summary || "").slice(0, 500) });
610	    } catch (e) {
611	      console.log(`[pi-web] 手动 /compact 失败: ${String(e?.message || e).slice(0, 120)}`);
612	      return json(res, 500, { error: "压缩失败：" + String(e?.message || e).slice(0, 120) });
613	    } finally {
614	      entry.busy = false;
615	    }
616	  }
