618	  // Plan Mode v2（Cursor/Claude Code 借鉴，工具级硬限制）：/plan <需求> → 只读调研+输出分步计划
619	  // v2 用 agent.setActiveToolsByName 把工具集硬切为只读集（read/search_files）——模型目录里没有写工具，
620	  // 无法调用 write/edit/bash/dsh/share，结构性杜绝违规（v1 仅指令约束靠模型自觉）；accept 时恢复全量。
621	  // unifiedChat 兑底路径在 handleUnifiedChat 内做工具定义层过滤（见下）。
622	  const planCmd = typeof message === "string" && message.trim().match(/^\/plan(?:\s+(accept|cancel|execute)\b)?\s*(.*)$/i);
623	  if (planCmd) {
624	    const pAct = (planCmd[1] || "").toLowerCase();
625	    const pRest = (planCmd[2] || "").trim();
626	    const applyPlanTools = async (readonly) => {
627	      if (!entry.agent) return; // agent 尚未创建（新会话首条 /plan），ensureAgent 后统一应用
628	      try {
629	        const names = readonly ? PLAN_READONLY_SET : entry.agent.getAllTools().map(t => t.name);
630	        entry.agent.setActiveToolsByName(names);
631	        console.log(`[plan] ${readonly ? "工具级限制生效（只读）" : "工具集已恢复全量"} → ${names.join(", ")}`);
632	      } catch (e) { console.log(`[plan] 工具集设置失败: ${String(e?.message || e).slice(0, 80)}`); }
633	    };
634	    if (!pAct) {
635	      if (!pRest) return json(res, 400, { error: "/plan 用法：/plan <需求> 进入规划模式；/plan accept 批准执行；/plan cancel 取消" });
636	      entry.planPending = true;
637	      await applyPlanTools(true);
638	      message = `【规划模式】请先只读调研（你的工具已被系统限制为只读，仅能读取/搜索文件，无法修改/创建/删除任何文件、无法运行写入或测试命令），然后输出一份分步实施计划：目标 / 实施步骤 / 涉及文件 / 风险点。计划用编号列表清晰输出，最后询问用户是否批准。\n\n需求：${pRest}`;
639	    } else if (pAct === "accept" || pAct === "execute") {
640	      entry.planPending = false;
641	      await applyPlanTools(false);
642	      message = `【批准规划】用户已批准你上一步输出的计划。请现在按计划开始执行（你的工具已恢复，可以正常读写文件、运行命令）。`;
643	    } else {
644	      entry.planPending = false;
645	      await applyPlanTools(false);
646	      return json(res, 200, { plan: "cancelled" });
647	    }
648	  }
