650	  // 绘图模型（id 含 image）→ 走图像生成接口（在写 SSE headers 之前处理）
651	  if (defaultModel && /image/i.test(defaultModel.id)) {
652	    try {
653	      const image = await generateImage(defaultModel.provider, defaultModel.id, message);
654	      if (image) return json(res, 200, { image, model: `${defaultModel.provider}/${defaultModel.id}` });
655	    } catch {}
656	    return json(res, 500, { error: "绘图失败（模型不支持图像生成或 Key 无效）" });
657	  }
