659	  if (defaultModel && /video/i.test(defaultModel.id)) {
660	    const r = await generateVideo(defaultModel.provider, defaultModel.id, message);
661	    if (r.video) return json(res, 200, { video: r.video, model: `${defaultModel.provider}/${defaultModel.id}` });
662	    return json(res, 500, { error: r.error || "视频生成失败" });
663	  }
664	
665	  res.writeHead(200, {
666	    "Content-Type": "text/event-stream",
667	    "Cache-Control": "no-cache",
