681	      if (bp === "auto" || /^auto(-smart)?$/i.test(bm)) {
682	        // 仅当会话本就处于 Auto（未切过具体模型）才保持；用户显式切过具体模型 → 不动，避免覆盖
683	        if (entry.modelKey && entry.modelKey.provider !== "auto" && entry.modelKey.id !== "auto") {
684	          // 已切具体模型：忽略 stale auto，保持用户选择
685	        } else if (!entry.modelKey || entry.modelKey.provider !== "auto") {
686	          entry.modelKey = { provider: "auto", id: "auto" };
687	          if (sessionId) saveSessionModelKey(sessionId, entry.modelKey);
688	        }
689	      } else {
690	        const same = entry.modelKey && entry.modelKey.provider === bp && entry.modelKey.id === bm;
691	        // ⚠️ 2026-08-19 收敛：前端 stale 显示值（localStorage 残留 nvidia/deepseek）不再同步进服务端——
692	        //   新会话一律默认千问，用户切模型走 /api/model 显式切换，只锁当前会话
693	        if (!same && modelList.find(m => m.provider === bp && m.id === bm)) {
694	          if (bp !== "deepseek" && bp !== "nvidia") {
695	            entry.modelKey = { provider: bp, id: bm };
696	            if (sessionId) saveSessionModelKey(sessionId, entry.modelKey);
697	            console.log(`[pi-web] 前端同步模型 → ${bp}/${bm}`);
