705	  // 通道策略：默认用 pi agent 官方管线（与 TUI 同源，工具执行/打断/竞态都成熟），
706	  // 自制 unifiedChat 仅作兑底（官方管线异常时降级）。设置 PI_USE_AGENT=0 可强制走 unifiedChat
707	  // ⚠️ 2026-08-27：请求的是非 SDK 原生通道（claude-relay/bigmodel/sensenova 等自定义中转）时，
708	  //    agent 路径会静默兑底到别的模型（选了它实际没跑到）→ 改走 unifiedChat 直连（任意 OpenAI 兼容可用）。
709	  const reqProv = (typeof body.model === "string" && body.model.includes("/"))
710	    ? body.model.split("/")[0]
711	    : null;
712	  const useAgent = process.env.PI_USE_AGENT !== "0" && !!defaultModel
713	    && (!reqProv || NATIVE_PROVIDERS.has(reqProv));
714	  if (defaultModel && !useAgent) {
715	    const hb2 = startSseHeartbeat(res);
716	    // 打断支持：客户端断开 SSE 时中止 unifiedChat（不再继续工具调用/模型请求）
717	    const abortCtrl = new AbortController();
718	    const onClose = () => { try { abortCtrl.abort(); } catch {} };
719	    req.on("close", onClose);
720	    try {
721	      await handleUnifiedChat(res, entry, message, sessionId || findKeyByEntry(entry), body.params, abortCtrl.signal, undefined, thinkOn, body.taskKey, (entry.modelKey && !isAutoModel(entry.modelKey)) ? entry.modelKey : null);
722	    } catch (e) {
723	      try { sseWrite(res, "error", { message: String(e?.message || e) }); } catch {}
724	    } finally {
