726	      req.removeListener("close", onClose);
727	      // 代次匹配才释放（快速重发时新请求已占 busy，旧请求不得干扰）
728	      if (entry.gen === thisGen) entry.busy = false;
729	      try { res.end(); } catch {}
730	      if (entry.gen === thisGen) invalidateSessionCache(); // 消息写入会话文件 → 列表缓存失效
731	    }
732	    return;
733	  }
