 36	export function parseSseBlocks(input: string): { events: RunEvent[]; rest: string } {
 37	  const normalized = input.replace(/\r\n/g, '\n')
 38	  const blocks = normalized.split('\n\n')
 39	  const rest = blocks.pop() || ''
 40	  const events: RunEvent[] = []
 41	  for (const block of blocks) {
 42	    if (!block || block.startsWith(':')) continue
 43	    const dataLines: string[] = []
 44	    for (const line of block.split('\n')) {
 45	      if (line.startsWith('data:')) dataLines.push(line.slice(5).trimStart())
 46	    }
 47	    if (!dataLines.length) continue
 48	    try {
 49	      const event = JSON.parse(dataLines.join('\n'))
 50	      if (event && Number.isInteger(event.seq) && event.runId) events.push(event)
 51	    } catch {}
 52	  }
 53	  return { events, rest }
 54	}
 55	
 56	export function isTerminalRunStatus(status: string): status is RunStatus {
 57	  return TERMINAL.has(status as RunStatus)
 58	}
