 24	  terminal: boolean
 25	} {
 26	  if (event.runId !== cursor.runId || !Number.isInteger(event.seq) || event.seq <= cursor.lastSeq) {
 27	    return { cursor, accepted: false, terminal: TERMINAL.has(cursor.status) }
 28	  }
 29	  const status = TERMINAL.has(event.type as RunStatus)
 30	    ? event.type as RunStatus
 31	    : cursor.status
 32	  const next = { ...cursor, lastSeq: event.seq, status }
 33	  return { cursor: next, accepted: true, terminal: TERMINAL.has(status) }
 34	}
